// planView is a plan with its price in major units ("12.50") and formatted for people ("$12.50").
type planView struct {
	store.Plan
	Price          string `json:"price"`
	PriceFormatted string `json:"price_formatted"`
}

func viewPlan(p store.Plan) planView {
	return planView{Plan: p, Price: fmt.Sprintf("%.2f", float64(p.UnitAmount)/100), PriceFormatted: money.Format(p.UnitAmount, p.Currency)}
}

func (s *Server) listPlans(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	items := []planView{}
	for _, pl := range s.store.Plans(p.OrgID) {
		items = append(items, viewPlan(pl))
	}
	writeJSON(w, http.StatusOK, list{Items: items})
}

// createPlan takes the price in major units, as a string ("12.50"), the way people type it.
func (s *Server) createPlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Name      string          `json:"name"`
		Currency  money.Currency  `json:"currency"`
		Price     string          `json:"price"`
		Interval  store.Interval  `json:"interval"`
		UsageType store.UsageType `json:"usage_type"`
		TrialDays int             `json:"trial_days"`
	}
	if !decode(w, r, &in) {
		return
	}
	amount, err := money.ParseMajor(in.Price, in.Currency)
	if err != nil {
		if errors.Is(err, money.ErrInvalidAmount) {
			writeError(w, http.StatusUnprocessableEntity, "invalid_amount", err.Error())
			return
		}
		s.storeError(w, err)
		return
	}
	pl, err := s.store.CreatePlan(store.Plan{OrgID: p.OrgID, Name: in.Name, Currency: in.Currency, UnitAmount: amount, Interval: in.Interval,
		UsageType: in.UsageType, TrialDays: in.TrialDays}, s.clock.Now())
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, viewPlan(pl))
}

func (s *Server) getPlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	pl, ok := s.store.Plan(p.OrgID, r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such plan")
		return
	}
	writeJSON(w, http.StatusOK, viewPlan(pl))
}

func (s *Server) updatePlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Name   *string `json:"name"`
		Active *bool   `json:"active"`
	}
	if !decode(w, r, &in) {
		return
	}
	pl, err := s.store.UpdatePlan(p.OrgID, r.PathValue("id"), func(pl *store.Plan) error {
		if in.Name != nil {
			pl.Name = *in.Name
		}
		if in.Active != nil {
			pl.Active = *in.Active
		}
		return nil
	})
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, viewPlan(pl))
}

// Package api is Tally's JSON HTTP API (version 1). Every request under /v1/ presents an API key as
// "Authorization: Bearer <token>"; the key acts as the member who created it, in that member's organization, with the
// member's current role. The API only ever shows the caller's organization's data.
package api

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"io"
	"log/slog"
	"net/http"
	"regexp"
	"strings"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/mail"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
	"example.com/tally/internal/webhooks"
)

// Options configure a Server.
type Options struct {
	Clock         clock.Clock            // nil: clock.Real
	Payments      *payments.Service      // required
	Subscriptions *subscriptions.Service // required
	Webhooks      *webhooks.Service      // nil: a service with the default HTTP client and resolver
	Mail          mail.Sender            // nil: an Outbox (nothing is sent)
	Logger        *slog.Logger           // nil: discard
	// BaseURL is the dashboard's address, for links in emails (default "https://app.tally.example").
	BaseURL string
}

// Server serves the API.
type Server struct {
	store   *store.Store
	clock   clock.Clock
	pay     *payments.Service
	subs    *subscriptions.Service
	hooks   *webhooks.Service
	mail    mail.Sender
	log     *slog.Logger
	baseURL string
	mux     *http.ServeMux
	handler http.Handler
}

// New returns a server over a store.
func New(st *store.Store, opt Options) *Server {
	if opt.Payments == nil || opt.Subscriptions == nil {
		panic("api.New: Options.Payments and Options.Subscriptions are required")
	}
	s := &Server{store: st, clock: opt.Clock, pay: opt.Payments, subs: opt.Subscriptions, hooks: opt.Webhooks, mail: opt.Mail, log: opt.Logger,
		baseURL: strings.TrimRight(opt.BaseURL, "/"), mux: http.NewServeMux()}
	if s.clock == nil {
		s.clock = clock.Real{}
	}
	if s.hooks == nil {
		s.hooks = webhooks.New(webhooks.Options{Store: st, Clock: s.clock})
	}
	if s.mail == nil {
		s.mail = &mail.Outbox{}
	}
	if s.log == nil {
		s.log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	if s.baseURL == "" {
		s.baseURL = "https://app.tally.example"
	}
	s.routes()
	s.handler = s.withRequestID(s.recoverPanics(s.mux))
	return s
}

// ServeHTTP implements http.Handler.
func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) { s.handler.ServeHTTP(w, r) }

func (s *Server) routes() {
	m := s.mux
	m.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
