package store

import (
	"errors"
	"fmt"
	"regexp"
	"sort"
	"strings"
	"time"
)

// Coupon errors. Callers check them with errors.Is.
var (
	ErrCodeTaken            = fmt.Errorf("%w: coupon code already in use", ErrConflict)
	ErrCouponAlreadyApplied = fmt.Errorf("%w: the subscription already has a coupon", ErrConflict)
	ErrSubscriptionCanceled = fmt.Errorf("%w: the subscription is canceled", ErrConflict)
	ErrCouponExpired        = errors.New("the coupon can no longer be redeemed")
	ErrCouponExhausted      = errors.New("the coupon has no redemptions left")
	ErrCurrencyMismatch     = errors.New("the coupon is in another currency than the subscription's plan")
)

var couponCodeRe = regexp.MustCompile(`^[A-Za-z0-9_-]{3,32}$`)

// CreateCoupon adds a coupon to an organization. Codes are unique in the organization, ignoring case.
func (s *Store) CreateCoupon(c Coupon, now time.Time) (Coupon, error) {
	if err := checkCoupon(c); err != nil {
		return Coupon{}, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[c.OrgID]; !ok {
		return Coupon{}, ErrNotFound
	}
	key := couponKey{c.OrgID, strings.ToLower(c.Code)}
	if _, ok := s.couponsByCode[key]; ok {
		return Coupon{}, ErrCodeTaken
	}
	c.ID = s.newID("cpn")
	c.CreatedAt = now.UTC()
	c = copyCoupon(c)
	s.coupons[c.ID] = c
	s.couponsByCode[key] = c.ID
	return copyCoupon(c), nil
}

func checkCoupon(c Coupon) error {
	if !couponCodeRe.MatchString(c.Code) {
		return invalid("a coupon code is 3 to 32 letters, digits, dashes or underscores")
	}
	hasPercent, hasAmount := c.PercentOff != 0, c.AmountOff != 0
	switch {
	case hasPercent == hasAmount:
		return invalid("a coupon takes exactly one of percent_off and amount_off")
	case hasPercent && (c.PercentOff < 1 || c.PercentOff > 100):
		return invalid("percent_off is 1 to 100")
	case hasPercent && c.Currency != "":
		return invalid("only an amount_off coupon has a currency")
	case hasAmount && c.AmountOff < 0:
		return invalid("amount_off is more than zero")
	case hasAmount && !c.Currency.Valid():
		return invalid("unknown currency %q", c.Currency)
	}
	switch c.Duration {
	case CouponOnce, CouponForever:
		if c.DurationInMonths != 0 {
			return invalid("duration_in_months is only for repeating coupons")
		}
	case CouponRepeating:
		if c.DurationInMonths < 1 || c.DurationInMonths > 36 {
			return invalid("a repeating coupon lasts 1 to 36 months")
		}
	default:
		return invalid("a coupon's duration is once, repeating or forever")
	}
	if c.MaxRedemptions < 0 {
		return invalid("max_redemptions is at least 1")
	}
	return nil
}

// Coupon returns one of an organization's coupons by its code, ignoring case.
func (s *Store) CouponByCode(orgID, code string) (Coupon, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.couponByCode(orgID, code)
}

func (s *Store) couponByCode(orgID, code string) (Coupon, bool) {
	id, ok := s.couponsByCode[couponKey{orgID, strings.ToLower(code)}]
	if !ok {
		return Coupon{}, false
	}
	return copyCoupon(s.coupons[id]), true
}

// Coupons returns an organization's coupons, oldest first.
func (s *Store) Coupons(orgID string) []Coupon {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Coupon{}
	for _, c := range s.coupons {
		if c.OrgID == orgID {
			out = append(out, copyCoupon(c))
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
			return out[i].CreatedAt.Before(out[j].CreatedAt)
		}
		return out[i].ID < out[j].ID
	})
	return out
}

// CouponRedemptions counts the organization's subscriptions that have the coupon with this code.
func (s *Store) CouponRedemptions(orgID, code string) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.couponRedemptions(orgID, code)
}

func (s *Store) couponRedemptions(orgID, code string) int {
	n := 0
	for _, sub := range s.subs {
		if sub.OrgID == orgID && sub.Coupon == code {
			n++
		}
	}
	return n
}

// RedeemCoupon applies the coupon with this code to a subscription at now. The checks and the change happen under one
// lock, so a coupon's max_redemptions cannot be exceeded by concurrent requests.
func (s *Store) RedeemCoupon(orgID, subID, code string, now time.Time) (Subscription, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	sub, ok := s.subs[subID]
	if !ok || sub.OrgID != orgID {
		return Subscription{}, ErrNotFound
	}
	c, ok := s.couponByCode(orgID, code)
	if !ok {
		return Subscription{}, ErrNotFound
	}
	switch {
	case sub.Coupon != "":
		return Subscription{}, ErrCouponAlreadyApplied
	case sub.Status == Canceled:
		return Subscription{}, ErrSubscriptionCanceled
	case c.RedeemBy != nil && now.After(*c.RedeemBy):
		return Subscription{}, ErrCouponExpired
	case c.MaxRedemptions > 0 && s.couponRedemptions(orgID, c.Code) >= c.MaxRedemptions:
		return Subscription{}, ErrCouponExhausted
	case c.Currency != "" && s.plans[sub.PlanID].Currency != c.Currency:
		return Subscription{}, ErrCurrencyMismatch
	}
	t := now.UTC()
	sub.Coupon, sub.CouponRedeemedAt = c.Code, &t
	s.subs[subID] = sub
	return copySub(sub), nil
}

func copyCoupon(c Coupon) Coupon {
	if c.RedeemBy != nil {
		t := *c.RedeemBy
		c.RedeemBy = &t
	}
	return c
}

