	out := []Coupon{}
	for _, c := range s.coupons {
		if c.OrgID == orgID {
			out = append(out, copyCoupon(c))
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
			return out[i].CreatedAt.Before(out[j].CreatedAt)
		}
		return out[i].ID < out[j].ID
	})
	return out
}

// CouponRedemptions counts the organization's subscriptions that have the coupon with this code.
func (s *Store) CouponRedemptions(orgID, code string) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.couponRedemptions(orgID, code)
}

func (s *Store) couponRedemptions(orgID, code string) int {
	n := 0
	for _, sub := range s.subs {
		if sub.OrgID == orgID && sub.Coupon == code {
			n++
		}
	}
	return n
}

// RedeemCoupon applies the coupon with this code to a subscription at now. The checks and the change happen under one
// lock, so a coupon's max_redemptions cannot be exceeded by concurrent requests.
func (s *Store) RedeemCoupon(orgID, subID, code string, now time.Time) (Subscription, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	sub, ok := s.subs[subID]
	if !ok || sub.OrgID != orgID {
		return Subscription{}, ErrNotFound
	}
	c, ok := s.couponByCode(orgID, code)
	if !ok {
		return Subscription{}, ErrNotFound
	}
	switch {
	case sub.Coupon != "":
		return Subscription{}, ErrCouponAlreadyApplied
	case sub.Status == Canceled:
		return Subscription{}, ErrSubscriptionCanceled
	case c.RedeemBy != nil && now.After(*c.RedeemBy):
		return Subscription{}, ErrCouponExpired
	case c.MaxRedemptions > 0 && s.couponRedemptions(orgID, c.Code) >= c.MaxRedemptions:
		return Subscription{}, ErrCouponExhausted
	case c.Currency != "" && s.plans[sub.PlanID].Currency != c.Currency:
		return Subscription{}, ErrCurrencyMismatch
	}
	t := now.UTC()
	sub.Coupon, sub.CouponRedeemedAt = c.Code, &t
	s.subs[subID] = sub
	return copySub(sub), nil
}

func copyCoupon(c Coupon) Coupon {
	if c.RedeemBy != nil {
		t := *c.RedeemBy
		c.RedeemBy = &t
	}
	return c
}

