// Compute returns an invoice's totals: the sum of its lines, the discount (DiscountPercent of the subtotal), and tax at the
// invoice's rate on the subtotal after the discount. The discount and the tax are each rounded half away from zero to a
// whole minor unit.
func Compute(inv store.Invoice) Totals {
	var subtotal int64
	for _, l := range inv.Lines {
		subtotal += l.Amount()
	}
	discount := money.Percent(subtotal, inv.DiscountPercent)
	taxable := subtotal - discount
	tax := money.BasisPoints(taxable, inv.TaxRateBP)
	return Totals{Subtotal: subtotal, Discount: discount, Tax: tax, Total: taxable + tax}
}

args.new_string:
// Compute returns an invoice's totals: the sum of its lines, the discount, and tax at the invoice's rate on the subtotal after
// the discount. The discount is the invoice's coupon's when it has one, otherwise DiscountPercent of the subtotal. The
// discount and the tax are each rounded half away from zero to a whole minor unit.
func Compute(inv store.Invoice) Totals {
	var subtotal int64
	for _, l := range inv.Lines {
		subtotal += l.Amount()
	}
	discount := discountOf(inv, subtotal)
	taxable := subtotal - discount
	tax := money.BasisPoints(taxable, inv.TaxRateBP)
	return Totals{Subtotal: subtotal, Discount: discount, Tax: tax, Total: taxable + tax}
}

// discountOf is the discount on an invoice with this subtotal.
func discountOf(inv store.Invoice, subtotal int64) int64 {
	switch {
	case inv.Coupon == "":
		return money.Percent(subtotal, inv.DiscountPercent)
	case inv.CouponPercentOff > 0:
		return money.Percent(subtotal, inv.CouponPercentOff)
	default:
		// An amount off never takes more than the subtotal, and a credit is not discounted.
		return max(0, min(inv.CouponAmountOff, subtotal))
	}
}

