// couponFor returns the subscription's coupon when it discounts the invoice of a period that starts at start. A coupon
// discounts the invoices created after it was applied: a once coupon only the first of them, a repeating coupon those whose
// period starts less than its duration after the redemption, and a forever coupon all of them. An amount off in another
// currency than the plan's (the plan may have changed since) is not applied.
func (s *Service) couponFor(sub store.Subscription, plan store.Plan, start time.Time) (store.Coupon, bool) {
	if sub.Coupon == "" || sub.CouponRedeemedAt == nil {
		return store.Coupon{}, false
	}
	c, ok := s.Store.CouponByCode(sub.OrgID, sub.Coupon)
	if !ok || (c.Currency != "" && c.Currency != plan.Currency) {
		return store.Coupon{}, false
	}
	switch c.Duration {
	case store.CouponForever:
		return c, true
	case store.CouponRepeating:
		return c, start.Before(sub.CouponRedeemedAt.AddDate(0, c.DurationInMonths, 0))
	default:
		for _, inv := range s.Store.ListInvoices(sub.OrgID, store.InvoiceFilter{SubscriptionID: sub.ID}) {
			if inv.Coupon == c.Code {
				return c, false
			}
		}
		return c, true
	}
}

