package store

import (
	"errors"
	"testing"
	"time"

	"example.com/tally/internal/money"
)

func TestCreateCouponValidation(t *testing.T) {
	s := New()
	org := newOrg(t, s, "Acme")
	valid := Coupon{OrgID: org.ID, Code: "SPRING_25", PercentOff: 25, Duration: CouponOnce}
	for name, c := range map[string]Coupon{
		"short code":            {OrgID: org.ID, Code: "AB", PercentOff: 5, Duration: CouponOnce},
		"long code":             {OrgID: org.ID, Code: "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456", PercentOff: 5, Duration: CouponOnce},
		"space in code":         {OrgID: org.ID, Code: "AB C", PercentOff: 5, Duration: CouponOnce},
		"neither amount":        {OrgID: org.ID, Code: "NONE", Duration: CouponOnce},
		"both amounts":          {OrgID: org.ID, Code: "BOTH", PercentOff: 5, AmountOff: 500, Currency: money.USD, Duration: CouponOnce},
		"percent over 100":      {OrgID: org.ID, Code: "OVER", PercentOff: 101, Duration: CouponOnce},
		"percent under 1":       {OrgID: org.ID, Code: "UNDER", PercentOff: -1, Duration: CouponOnce},
		"percent with currency": {OrgID: org.ID, Code: "CUR", PercentOff: 5, Currency: money.USD, Duration: CouponOnce},
		"amount without currency": {OrgID: org.ID, Code: "NOCUR", AmountOff: 500, Duration: CouponOnce},
		"unknown duration":      {OrgID: org.ID, Code: "DUR", PercentOff: 5, Duration: "yearly"},
		"months on once":        {OrgID: org.ID, Code: "ONCEM", PercentOff: 5, Duration: CouponOnce, DurationInMonths: 3},
		"repeating without months": {OrgID: org.ID, Code: "REPNO", PercentOff: 5, Duration: CouponRepeating},
		"repeating 37 months":   {OrgID: org.ID, Code: "REP37", PercentOff: 5, Duration: CouponRepeating, DurationInMonths: 37},
		"negative max":          {OrgID: org.ID, Code: "MAXNEG", PercentOff: 5, Duration: CouponForever, MaxRedemptions: -1},
	} {
		if _, err := s.CreateCoupon(c, t0); !errors.Is(err, ErrInvalid) {
			t.Errorf("%s: err = %v, want ErrInvalid", name, err)
		}
	}
	if _, err := s.CreateCoupon(Coupon{OrgID: "org_missing", Code: "GHOST", PercentOff: 5, Duration: CouponForever}, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("unknown org: %v", err)
	}
	c, err := s.CreateCoupon(valid, t0)
	if err != nil || c.ID == "" || c.CreatedAt != t0 || c.Code != "SPRING_25" {
		t.Fatalf("valid coupon = %+v, %v", c, err)
	}
}

func TestCouponCodesAreUniquePerOrganizationIgnoringCase(t *testing.T) {
	s := New()
	acme, globex := newOrg(t, s, "Acme"), newOrg(t, s, "Globex")
	if _, err := s.CreateCoupon(Coupon{OrgID: acme.ID, Code: "Launch", PercentOff: 10, Duration: CouponForever}, t0); err != nil {
		t.Fatal(err)
	}
	if _, err := s.CreateCoupon(Coupon{OrgID: acme.ID, Code: "LAUNCH", PercentOff: 20, Duration: CouponForever}, t0); !errors.Is(err, ErrCodeTaken) {
		t.Fatalf("same code, other case: %v", err)
	}
	if _, err := s.CreateCoupon(Coupon{OrgID: globex.ID, Code: "launch", AmountOff: 500, Currency: money.EUR, Duration: CouponOnce}, t0); err != nil {
		t.Fatalf("another organization: %v", err)
	}
	if c, ok := s.CouponByCode(acme.ID, "lAuNcH"); !ok || c.PercentOff != 10 {
		t.Fatalf("CouponByCode = %+v, %v", c, ok)
	}
	if _, ok := s.CouponByCode(globex.ID, "missing"); ok {
		t.Fatal("found a coupon that does not exist")
	}
	if got := s.Coupons(acme.ID); len(got) != 1 {
		t.Fatalf("Coupons = %+v", got)
	}
}

func TestRedeemCoupon(t *testing.T) {
	s := New()
	org := newOrg(t, s, "Acme")
	other := newOrg(t, s, "Globex")
	cus, _ := s.CreateCustomer(org.ID, "Jane", "jane@example.com", t0)
	usd, _ := s.CreatePlan(Plan{OrgID: org.ID, Name: "Team", Currency: money.USD, UnitAmount: 2000, Interval: Monthly}, t0)
	eur, _ := s.CreatePlan(Plan{OrgID: org.ID, Name: "Team EUR", Currency: money.EUR, UnitAmount: 2000, Interval: Monthly}, t0)
	newSub := func(planID string) Subscription {
		t.Helper()
		sub, err := s.CreateSubscription(Subscription{OrgID: org.ID, CustomerID: cus.ID, PlanID: planID, Quantity: 1, Status: Active}, t0)
