func TestRedeemCoupon(t *testing.T) {
	s := New()
	org := newOrg(t, s, "Acme")
	other := newOrg(t, s, "Globex")
	cus, _ := s.CreateCustomer(org.ID, "Jane", "jane@example.com", t0)
	usd, _ := s.CreatePlan(Plan{OrgID: org.ID, Name: "Team", Currency: money.USD, UnitAmount: 2000, Interval: Monthly}, t0)
	eur, _ := s.CreatePlan(Plan{OrgID: org.ID, Name: "Team EUR", Currency: money.EUR, UnitAmount: 2000, Interval: Monthly}, t0)
	newSub := func(planID string) Subscription {
		t.Helper()
		sub, err := s.CreateSubscription(Subscription{OrgID: org.ID, CustomerID: cus.ID, PlanID: planID, Quantity: 1, Status: Active}, t0)
		if err != nil {
			t.Fatal(err)
		}
		return sub
	}
	expires := t0.Add(time.Hour)
	mk := func(c Coupon) Coupon { c.OrgID = org.ID; return c }
	if _, err := s.CreateCoupon(mk(Coupon{Code: "OFF10", PercentOff: 10, Duration: CouponForever}), t0); err != nil {
		t.Fatal(err)
	}
	if _, err := s.CreateCoupon(mk(Coupon{Code: "ONCE", PercentOff: 10, Duration: CouponOnce, MaxRedemptions: 1}), t0); err != nil {
		t.Fatal(err)
	}
	if _, err := s.CreateCoupon(mk(Coupon{Code: "LATE", PercentOff: 10, Duration: CouponOnce, RedeemBy: &expires}), t0); err != nil {
		t.Fatal(err)
	}
	if _, err := s.CreateCoupon(mk(Coupon{Code: "EURO", AmountOff: 500, Currency: money.EUR, Duration: CouponForever}), t0); err != nil {
		t.Fatal(err)
	}

	sub := newSub(usd.ID)
	got, err := s.RedeemCoupon(org.ID, sub.ID, "off10", t0)
	if err != nil || got.Coupon != "OFF10" || got.CouponRedeemedAt == nil || !got.CouponRedeemedAt.Equal(t0) {
		t.Fatalf("redeem = %+v, %v", got, err)
	}
	if stored, _ := s.Subscription(org.ID, sub.ID); stored.Coupon != "OFF10" {
		t.Fatalf("stored = %+v", stored)
	}
	if _, err := s.RedeemCoupon(org.ID, sub.ID, "ONCE", t0); !errors.Is(err, ErrCouponAlreadyApplied) {
		t.Fatalf("second coupon: %v", err)
	}
	if _, err := s.RedeemCoupon(other.ID, sub.ID, "OFF10", t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("subscription of another organization: %v", err)
	}
	if _, err := s.RedeemCoupon(org.ID, newSub(usd.ID).ID, "OFF10x", t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("no such coupon: %v", err)
	}
	if _, err := s.RedeemCoupon(org.ID, newSub(usd.ID).ID, "OFF10", t0); err != nil {
		t.Fatalf("forever coupon, second subscription: %v", err)
	}
	if n := s.CouponRedemptions(org.ID, "OFF10"); n != 2 {
		t.Fatalf("redemptions = %d", n)
	}

	if _, err := s.RedeemCoupon(org.ID, newSub(usd.ID).ID, "ONCE", t0); err != nil {
		t.Fatalf("first use of a max 1 coupon: %v", err)
	}
	if _, err := s.RedeemCoupon(org.ID, newSub(usd.ID).ID, "ONCE", t0); !errors.Is(err, ErrCouponExhausted) {
		t.Fatalf("max 1 coupon, second use: %v", err)
	}
	if _, err := s.RedeemCoupon(org.ID, newSub(usd.ID).ID, "LATE", expires); err != nil {
		t.Fatalf("redeem_by is the last moment: %v", err)
	}
	if _, err := s.RedeemCoupon(org.ID, newSub(usd.ID).ID, "LATE", expires.Add(time.Second)); !errors.Is(err, ErrCouponExpired) {
		t.Fatalf("after redeem_by: %v", err)
	}
	if _, err := s.RedeemCoupon(org.ID, newSub(eur.ID).ID, "EURO", t0); !errors.Is(err, ErrCurrencyMismatch) {
		t.Fatalf("EUR coupon on a USD plan: %v", err)
	}
	if _, err := s.RedeemCoupon(org.ID, newSub(usd.ID).ID, "EURO", t0); !errors.Is(err, ErrCurrencyMismatch) {
		t.Fatalf("EUR coupon on a USD plan again: %v", err)
	}
	canceled := newSub(usd.ID)
	if _, err := s.UpdateSubscription(org.ID, canceled.ID, func(x *Subscription) error { x.Status = Canceled; return nil }); err != nil {
		t.Fatal(err)
	}
	if _, err := s.RedeemCoupon(org.ID, canceled.ID, "OFF10", t0); !errors.Is(err, ErrSubscriptionCanceled) {
		t.Fatalf("canceled subscription: %v", err)
	}
}

