package subscriptions_test

import (
	"context"
	"testing"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/billing"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
)

// couponSubscription starts a monthly 20.00 USD subscription for a customer who pays by card, then applies coupon to it.
func couponSubscription(t *testing.T, e *apitest.Env, coupon store.Coupon, discountPercent int) store.Subscription {
	t.Helper()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(context.Background(), e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1, DiscountPercent: discountPercent})
	if err != nil {
		t.Fatal(err)
	}
	coupon.OrgID = e.Acme.ID
	if _, err := e.Store.CreateCoupon(coupon, e.Clock.Now()); err != nil {
		t.Fatal(err)
	}
	if sub, err = e.Store.RedeemCoupon(e.Acme.ID, sub.ID, coupon.Code, e.Clock.Now()); err != nil {
		t.Fatal(err)
	}
	return sub
}

// renew moves the clock to the end of the subscription's period and renews it.
func renew(t *testing.T, e *apitest.Env, sub store.Subscription) {
	t.Helper()
	cur, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	e.Clock.Set(cur.CurrentPeriodEnd)
	if n, err := e.Subs.RenewDue(context.Background()); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
}

// invoicesOf returns the subscription's invoices, oldest first.
func invoicesOf(e *apitest.Env, sub store.Subscription) []store.Invoice {
	return e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
}

func TestForeverPercentCouponReplacesDiscountPercent(t *testing.T) {
	e := apitest.New(t)
	sub := couponSubscription(t, e, store.Coupon{Code: "FOREVER25", PercentOff: 25, Duration: store.CouponForever}, 10)
	renew(t, e, sub)
	renew(t, e, sub)

	invs := invoicesOf(e, sub)
	if len(invs) != 3 {
		t.Fatalf("%d invoices", len(invs))
	}
	// The first invoice came before the coupon, so the subscription's 10 percent applies to it.
	if invs[0].Coupon != "" || billing.Compute(invs[0]).Total != 1800 {
		t.Fatalf("first invoice = %+v", invs[0])
	}
	for _, inv := range invs[1:] {
		if inv.Coupon != "FOREVER25" || inv.DiscountPercent != 0 || billing.Compute(inv).Discount != 500 || billing.Compute(inv).Total != 1500 {
			t.Fatalf("renewal invoice = %+v", inv)
		}
	}
	if cs := e.Gateway.Charges(); len(cs) != 3 || cs[0].Amount != 1800 || cs[1].Amount != 1500 || cs[2].Amount != 1500 {
		t.Fatalf("charges = %+v", cs)
	}
}

func TestOnceAmountCouponDiscountsOnlyTheFirstRenewal(t *testing.T) {
	e := apitest.New(t)
	sub := couponSubscription(t, e, store.Coupon{Code: "FIVEOFF", AmountOff: 500, Currency: "USD", Duration: store.CouponOnce}, 0)
	renew(t, e, sub)
	renew(t, e, sub)

	invs := invoicesOf(e, sub)
	if len(invs) != 3 {
		t.Fatalf("%d invoices", len(invs))
	}
	if invs[1].Coupon != "FIVEOFF" || billing.Compute(invs[1]).Total != 1500 {
		t.Fatalf("first renewal = %+v", invs[1])
	}
	if invs[2].Coupon != "" || billing.Compute(invs[2]).Discount != 0 || billing.Compute(invs[2]).Total != 2000 {
		t.Fatalf("second renewal = %+v", invs[2])
	}
}

func TestRepeatingCouponDiscountsItsMonths(t *testing.T) {
	e := apitest.New(t)
	sub := couponSubscription(t, e, store.Coupon{Code: "HALFTWICE", PercentOff: 50, Duration: store.CouponRepeating, DurationInMonths: 2}, 0)
	renew(t, e, sub) // the period starts one month after the redemption
	renew(t, e, sub) // the period starts two months after it: no longer discounted

	invs := invoicesOf(e, sub)
	if len(invs) != 3 {
		t.Fatalf("%d invoices", len(invs))
	}
	if invs[1].Coupon != "HALFTWICE" || billing.Compute(invs[1]).Total != 1000 {
		t.Fatalf("first renewal = %+v", invs[1])
	}
	if invs[2].Coupon != "" || billing.Compute(invs[2]).Total != 2000 {
		t.Fatalf("second renewal = %+v", invs[2])
	}
}

