func invoicesOf(e *apitest.Env, sub store.Subscription) []store.Invoice {
	return e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
}

func TestForeverPercentCouponReplacesDiscountPercent(t *testing.T) {
	e := apitest.New(t)
	sub := couponSubscription(t, e, store.Coupon{Code: "FOREVER25", PercentOff: 25, Duration: store.CouponForever}, 10)
	renew(t, e, sub)
	renew(t, e, sub)

	invs := invoicesOf(e, sub)
	if len(invs) != 3 {
		t.Fatalf("%d invoices", len(invs))
	}
	// The first invoice came before the coupon, so the subscription's 10 percent applies to it.
	if invs[0].Coupon != "" || billing.Compute(invs[0]).Total != 1800 {
		t.Fatalf("first invoice = %+v", invs[0])
	}
	for _, inv := range invs[1:] {
		if inv.Coupon != "FOREVER25" || inv.DiscountPercent != 0 || billing.Compute(inv).Discount != 500 || billing.Compute(inv).Total != 1500 {
			t.Fatalf("renewal invoice = %+v", inv)
		}
	}
	if cs := e.Gateway.Charges(); len(cs) != 3 || cs[0].Amount != 1800 || cs[1].Amount != 1500 || cs[2].Amount != 1500 {
		t.Fatalf("charges = %+v", cs)
	}
}

func TestOnceAmountCouponDiscountsOnlyTheFirstRenewal(t *testing.T) {
