func TestApplyCoupon(t *testing.T) {
	e := apitest.New(t)
	key := e.Acme.Key
	cus := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	usd := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	eur := e.CreatePlan(e.Acme, "Team EUR", "EUR", "20.00")
	newSub := func(planID string) store.Subscription {
		t.Helper()
		var sub store.Subscription
		e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", key, map[string]any{"customer_id": cus.ID, "plan_id": planID, "quantity": 1}, &sub)
		return sub
	}
	coupon := func(body map[string]any) {
		t.Helper()
		e.MustDo(http.StatusCreated, "POST", "/v1/coupons", key, body, nil)
	}
	apply := func(sub store.Subscription, code string) *apitest.Response {
		t.Helper()
		return e.Do("POST", "/v1/subscriptions/"+sub.ID+"/coupon", key, map[string]any{"code": code})
	}
	coupon(map[string]any{"code": "SPRING25", "percent_off": 25, "duration": "forever"})
	coupon(map[string]any{"code": "FIVE_OFF", "amount_off": "5.00", "currency": "USD", "duration": "once"})
	coupon(map[string]any{"code": "ONEUSE", "percent_off": 10, "duration": "forever", "max_redemptions": 1})
	coupon(map[string]any{"code": "LASTDAY", "percent_off": 10, "duration": "once", "redeem_by": apitest.Start.Add(24 * time.Hour).Format(time.RFC3339)})

	sub := newSub(usd.ID)
	if r := apply(sub, "NOPE"); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("no such coupon: %s", r)
	}
	var applied store.Subscription
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+sub.ID+"/coupon", key, map[string]any{"code": "spring25"}, &applied)
	if applied.Coupon != "SPRING25" || applied.CouponRedeemedAt == nil {
		t.Fatalf("applied = %+v", applied)
	}
	if r := apply(sub, "FIVE_OFF"); r.Code != http.StatusConflict || r.Map(t)["error"] != "coupon_already_applied" {
		t.Fatalf("second coupon: %s", r)
	}
	if r := apply(newSub(eur.ID), "FIVE_OFF"); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "currency_mismatch" {
		t.Fatalf("currency: %s", r)
	}
	if r := apply(newSub(usd.ID), "ONEUSE"); r.Code != http.StatusOK {
		t.Fatalf("first redemption of a max 1 coupon: %s", r)
	}
	if r := apply(newSub(usd.ID), "ONEUSE"); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "coupon_exhausted" {
		t.Fatalf("exhausted: %s", r)
	}
	var one couponJSON
	e.MustDo(http.StatusOK, "GET", "/v1/coupons/ONEUSE", key, nil, &one)
	if one.TimesRedeemed != 1 {
		t.Fatalf("times_redeemed = %d", one.TimesRedeemed)
	}

	canceled := newSub(usd.ID)
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+canceled.ID+"/cancel", key, nil, &canceled)
	if r := apply(canceled, "SPRING25"); r.Code != http.StatusConflict || r.Map(t)["error"] != "subscription_canceled" {
		t.Fatalf("canceled: %s", r)
	}

	e.Clock.Advance(48 * time.Hour)
	if r := apply(newSub(usd.ID), "LASTDAY"); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "coupon_expired" {
		t.Fatalf("expired: %s", r)
	}

	// The discount shows on the renewal of the subscription that has SPRING25, and the subscription shows the coupon.
	e.Clock.Set(applied.CurrentPeriodEnd)
	if _, err := e.Subs.RenewDue(e.T.(interface{ Context() any }) == nil && false || true); err != nil {
		t.Fatal(err)
	}
	var invs struct {
		Items []struct {
			store.Invoice
			Discount int64
			Total    int64
		}
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices?subscription_id="+applied.ID, key, nil, &invs)
	if len(invs.Items) != 2 {
		t.Fatalf("invoices = %+v", invs.Items)
	}
	renewal := invs.Items[1]
	if renewal.Coupon != "SPRING25" || renewal.Discount != 500 || renewal.Total != 1500 || renewal.DiscountPercent != 0 {
		t.Fatalf("renewal = %+v", renewal)
	}
	if first := invs.Items[0]; first.Coupon != "" {
		t.Fatalf("first invoice = %+v", first)
	}
}

