250		if !inv.Currency.Valid() {
251			return Invoice{}, invalid("unknown currency %q", inv.Currency)
252		}
253		if inv.DiscountPercent < 0 || inv.DiscountPercent > 100 {
254			return Invoice{}, invalid("the discount is 0 to 100 percent")
255		}
